import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, BoxGeometry, Color } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Dimensions ---
  const width = 6.0;
  const height = 0.6;
  const dividerHeight = 0.02;
  const dividerY = -height / 2 + 0.05; // just below the row

  // --- Background plane ---
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: new Color(config.colors?.surface || '#0b0b10'),
    transparent: true,
    opacity: 0.9,
  });
  const plane = new Mesh(geometry, material);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // --- Load texture ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Divider line ---
  const dividerGeo = new PlaneGeometry(width - 0.4, dividerHeight);
  const dividerMat = new MeshBasicNodeMaterial({
    color: new Color(config.colors?.paper || '#e8ecf2'),
    transparent: true,
    opacity: 0.3,
  });
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, dividerY, 0.01); // slightly in front
  group.add(divider);

  // --- Accent edge (border) ---
  // We'll create a thin border around the plane using a line or a set of thin boxes.
  // For simplicity, create a border using a single thin rectangle that is slightly larger than the plane.
  const borderThickness = 0.02;
  const borderGeo = new PlaneGeometry(width + borderThickness * 2, height + borderThickness * 2);
  const borderMat = new MeshBasicNodeMaterial({
    color: new Color(config.colors?.accent || '#ff2a38'),
    transparent: true,
    opacity: 0,
    side: ctx.THREE.DoubleSide,
  });
  const border = new Mesh(borderGeo, borderMat);
  border.position.set(0, 0, -0.01); // behind the plane
  group.add(border);

  // --- Store original position for hover ---
  const originalY = group.position.y; // but group position is set by scene placement, we need to store relative offset
  // Actually the group's position is set by scene placement. We'll store the plane's local y offset? Better to store the group's y and animate group.
  // But the hover effect should lift the entire row. So we'll animate the group's y.
  // However, the group's position is set externally. We'll store the initial group position y.
  // But we don't know it at creation time. We'll store a reference to the group and animate its position.y relative to its current.
  // We'll use a variable to track the base y.
  let baseY = 0; // will be set when group is added to scene? Actually we can set it after creation.
  // We'll store a flag to know if we have set baseY.
  let baseYSet = false;

  // --- Hover animation ---
  const hoverTimeline = gsap.timeline({ paused: true });
  // We'll define the animation later when we know baseY.

  // --- Click animation ---
  const clickTimeline = gsap.timeline({ paused: true });
  clickTimeline.to(group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(1.7)' })
    .to(group.scale, { x: 1, y: 1, duration: 0.3, ease: 'power4.out' });

  // --- Handlers ---
  const handlers = {
    pointerover: () => {
      if (!baseYSet) {
        baseY = group.position.y;
        baseYSet = true;
      }
      gsap.to(group.position, { y: baseY + 0.15, duration: 0.3, ease: 'power2.out' });
      // Show accent border
      gsap.to(borderMat, { opacity: 1, duration: 0.3, ease: 'power2.out' });
    },
    pointerout: () => {
      gsap.to(group.position, { y: baseY, duration: 0.3, ease: 'power2.out' });
      gsap.to(borderMat, { opacity: 0, duration: 0.3, ease: 'power2.out' });
    },
    click: () => {
      // Press-down animation
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
        onComplete: () => {
          gsap.to(group.scale, { x: 1, y: 1, duration: 0.3, ease: 'power4.out' });
        }
      });
      // Emit event
      ctx.emit('hub-collection.select', {});
    }
  };

  // --- Attach handlers ---
  group.userData.handlers = handlers;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
    // Kill any GSAP tweens on this group
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(borderMat);
    // Also kill any timelines we created
    hoverTimeline.kill();
    clickTimeline.kill();
  };

  return group;
}
